<?php $image = $recipe['images'][0] ?? null; ?><article class="recipe-card"><a class="recipe-card__media" href="/recipe/<?= e($recipe['id']) ?>"><img src="<?= e($image ? '/uploads/' . $image : '/assets/img/placeholder.svg') ?>" alt="<?= e($recipe['title']) ?>"></a><div class="recipe-card__body"><div class="recipe-card__rating">★ <?= e(number_format((float) ($recipe['rating_avg'] ?? 0), 1)) ?> <span class="muted">(<?= e((string) ($recipe['rating_count'] ?? 0)) ?>)</span></div><h3><a href="/recipe/<?= e($recipe['id']) ?>"><?= e($recipe['title']) ?></a></h3><p><?= e($recipe['description']) ?></p><div class="tag-list"><?php foreach (array_slice($recipe['tags'] ?? [], 0, 3) as $tag): ?><span class="tag"><?= e($tag) ?></span><?php endforeach; ?></div></div></article>
